import{_ as i,a0 as l,w as p,s,ao as d,I as a,x as r,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"用瀏覽器管理 Docker | LCTT x X-CMD","titleTemplate":false,"description":"用瀏覽器管理 Docker | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用瀏覽器管理 Docker | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用瀏覽器管理 Docker | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 How to Setup DockerUI--a Web Interface for Docker","title":"用瀏覽器管理 Docker","tag":"201511","desc":""},"relativePath":"201511/20151012 How to Setup DockerUI--a Web Interface for Docker.md","filePath":"[post].md"}'),c={name:"201511/20151012 How to Setup DockerUI--a Web Interface for Docker.md"};function k(u,e,h,m,b,x){const o=l("Link");return p(),s("div",null,[e[24]||(e[24]=d(`<h1 id="用瀏覽器管理-docker" tabindex="-1">用瀏覽器管理 Docker <a class="header-anchor" href="#用瀏覽器管理-docker" aria-label="Permalink to “用瀏覽器管理 Docker”">​</a></h1><p>Docker 越來越流行了。在一個容器裏面而不是虛擬機裏運行一個完整的操作系統是一種非常棒的技術和想法。docker 已經通過節省工作時間來拯救了成千上萬的系統管理員和開發人員。這是一個開源技術，提供一個平台來把應用程序當作容器來打包、分發、共享和運行，而不用關注主機上運行的操作系統是什麼。它沒有開發語言、框架或打包系統的限制，並且可以在任何時間、任何地點運行，從小型計算機到高端服務器都可以。運行 docker 容器和管理它們可能會花費一點點努力和時間，所以現在有一款基於 web 的應用程序－DockerUI，可以讓管理和運行容器變得很簡單。DockerUI 是一個對那些不熟悉 Linux 命令列，但又很想運行容器化程序的人很有幫助的工具。DockerUI 是一個開源的基於 web 的應用程序，它最值得稱道的是它華麗的設計和用來運行和管理 docker 的簡潔的操作界面。</p><p>下面會介紹如何在 Linux 上安裝配置 DockerUI。</p><h3 id="_1-安裝-docker" tabindex="-1">1. 安裝 docker <a class="header-anchor" href="#_1-安裝-docker" aria-label="Permalink to “1. 安裝 docker”">​</a></h3><p>首先，我們需要安裝 docker。我們得感謝 docker 的開發者，讓我們可以簡單的在主流 linux 發行版上安裝 docker。為了安裝 docker，我們得在對應的發行版上使用下面的命令。</p><h4 id="ubuntu-fedora-centos-rhel-debian" tabindex="-1">Ubuntu/Fedora/CentOS/RHEL/Debian <a class="header-anchor" href="#ubuntu-fedora-centos-rhel-debian" aria-label="Permalink to “Ubuntu/Fedora/CentOS/RHEL/Debian”">​</a></h4><p>docker 維護者已經寫了一個非常棒的腳本，用它可以在 Ubuntu 15.04/14.10/14.04、 CentOS 6.x/7、 Fedora 22、 RHEL 7 和 Debian 8.x 這幾個 linux 發行版上安裝 docker。這個腳本可以識別出我們的機器上運行的 linux 的發行版本，然後將需要的源庫添加到文件系統、並更新本地的安裝源目錄，最後安裝 docker 及其依賴庫。要使用這個腳本安裝docker，我們需要在 root 用户或者 sudo 權限下運行如下的命令，</p><pre><code># curl -sSL https://get.docker.com/ | sh
</code></pre><h4 id="opensuse-suse-linux-企業版" tabindex="-1">OpenSuse/SUSE Linux 企業版 <a class="header-anchor" href="#opensuse-suse-linux-企業版" aria-label="Permalink to “OpenSuse/SUSE Linux 企業版”">​</a></h4><p>要在運行了 OpenSuse 13.1/13.2 或者 SUSE Linux Enterprise Server 12 的機器上安裝 docker，我們只需要簡單的執行zypper 命令。運行下面的命令就可以安裝最新版本的docker：</p><pre><code># zypper in docker
</code></pre><h4 id="archlinux" tabindex="-1">ArchLinux <a class="header-anchor" href="#archlinux" aria-label="Permalink to “ArchLinux”">​</a></h4><p>docker 在 ArchLinux 的官方源和社區維護的 AUR 庫中可以找到。所以在 ArchLinux 上我們有兩種方式來安裝 docker。使用官方源安裝，需要執行下面的 pacman 命令：</p><pre><code># pacman -S docker
</code></pre><p>如果要從社區源 AUR 安裝 docker，需要執行下面的命令：</p><pre><code># yaourt -S docker-git
</code></pre><h3 id="_2-啓動" tabindex="-1">2. 啓動 <a class="header-anchor" href="#_2-啓動" aria-label="Permalink to “2. 啓動”">​</a></h3><p>安裝好 docker 之後，我們需要運行 docker 守護進程，然後才能運行並管理 docker 容器。我們需要使用下列命令來確認 docker 守護進程已經安裝並運行了。</p><h4 id="在-sysvinit-上" tabindex="-1">在 SysVinit 上#### <a class="header-anchor" href="#在-sysvinit-上" aria-label="Permalink to “在 SysVinit 上####”">​</a></h4><pre><code># service docker start
</code></pre><h4 id="在systemd-上" tabindex="-1">在Systemd 上#### <a class="header-anchor" href="#在systemd-上" aria-label="Permalink to “在Systemd 上####”">​</a></h4><pre><code># systemctl start docker
</code></pre><h3 id="_3-安裝-dockerui" tabindex="-1">3. 安裝 DockerUI <a class="header-anchor" href="#_3-安裝-dockerui" aria-label="Permalink to “3. 安裝 DockerUI”">​</a></h3><p>安裝 DockerUI 比安裝 docker 要簡單很多。我們僅僅需要從 docker 註冊庫上拉取 dockerui ，然後在容器裏面運行。要完成這些，我們只需要簡單的執行下面的命令：</p><pre><code># docker run -d -p 9000:9000 --privileged -v /var/run/docker.sock:/var/run/docker.sock dockerui/dockerui
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/starting-dockerui-container.png" alt="Starting DockerUI Container"></p><p>在上面的命令裏，dockerui 使用的默認端口是9000，我們需要使用<code>-p</code> 命令映射默認端口。使用<code>-v</code> 標誌我們可以指定docker 的 socket。如果主機使用了 SELinux 那麼就得使用<code>--privileged</code> 標誌。</p><p>執行完上面的命令後，我們要檢查 DockerUI 容器是否運行了，或者使用下面的命令檢查：</p><pre><code># docker ps
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/running-docker-containers.png" alt="Running Docker Containers"></p><h3 id="_4-拉取-docker-鏡像" tabindex="-1">4. 拉取 docker 鏡像 <a class="header-anchor" href="#_4-拉取-docker-鏡像" aria-label="Permalink to “4. 拉取 docker 鏡像”">​</a></h3><p>現在我們還不能直接使用 DockerUI 拉取鏡像，所以我們需要在命令列下拉取 docker 鏡像。要完成這些我們需要執行下面的命令。</p><pre><code># docker pull ubuntu
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/docker-image-pull.png" alt="Docker Image Pull"></p>`,34)),a("p",null,[e[1]||(e[1]=r("上面的命令將會從 docker 官方源 ",-1)),t(o,{href:"https://hub.docker.com/"},{default:n(()=>[...e[0]||(e[0]=[r("Docker Hub",-1)])]),_:1}),e[2]||(e[2]=r("拉取一個標誌為 ubuntu 的鏡像。類似的我們可以從 Hub 拉取需要的其它鏡像。",-1))]),e[25]||(e[25]=a("h3",{id:"_4-管理",tabindex:"-1"},[r("4. 管理 "),a("a",{class:"header-anchor",href:"#_4-管理","aria-label":"Permalink to “4. 管理”"},"​")],-1)),e[26]||(e[26]=a("p",null,"啓動了 DockerUI 容器之後，我們可以用它來執行啓動、暫停、終止、刪除以及 DockerUI 提供的其它操作 docker 容器的命令。",-1)),a("p",null,[e[5]||(e[5]=r("首先，我們需要在 web 瀏覽器裏面打開 dockerui：在瀏覽器裏面輸入 ",-1)),t(o,{href:"http://ip-address:9000"},{default:n(()=>[...e[3]||(e[3]=[r("http://ip-address:9000",-1)])]),_:1}),e[6]||(e[6]=r(" 或者 ",-1)),t(o,{href:"http://mydomain.com:9000"},{default:n(()=>[...e[4]||(e[4]=[r("http://mydomain.com:9000",-1)])]),_:1}),e[7]||(e[7]=r("，具體要根據你的系統配置。默認情況下登錄不需要認證，但是可以配置我們的 web 服務器來要求登錄認證。要啓動一個容器，我們需要有包含我們要運行的程序的鏡像。",-1))]),e[27]||(e[27]=d('<h4 id="創建" tabindex="-1">創建 <a class="header-anchor" href="#創建" aria-label="Permalink to “創建”">​</a></h4><p>創建容器我們需要在 Images 頁面裏，點擊我們想創建的容器的鏡像 id。然後點擊 <code>Create</code> 按鈕，接下來我們就會被要求輸入創建容器所需要的屬性。這些都完成之後，我們需要點擊按鈕<code>Create</code> 完成最終的創建。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/creating-docker-container.png" alt="Creating Docker Container"></p><h4 id="停止" tabindex="-1">停止 <a class="header-anchor" href="#停止" aria-label="Permalink to “停止”">​</a></h4><p>要停止一個容器，我們只需要跳轉到<code>Containers</code> 頁面，然後選取要停止的容器。然後在 Action 的子菜單裏面按下 Stop 就行了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/10/managing-container.png" alt="Managing Container"></p><h4 id="暫停與恢復" tabindex="-1">暫停與恢復 <a class="header-anchor" href="#暫停與恢復" aria-label="Permalink to “暫停與恢復”">​</a></h4><p>要暫停一個容器，只需要簡單的選取目標容器，然後點擊 Pause 就行了。恢復一個容器只需要在 Actions 的子菜單裏面點擊 Unpause 就行了。</p><h4 id="刪除" tabindex="-1">刪除 <a class="header-anchor" href="#刪除" aria-label="Permalink to “刪除”">​</a></h4><p>類似於我們上面完成的任務，殺掉或者刪除一個容器或鏡像也是很簡單的。只需要檢查、選擇容器或鏡像，然後點擊 Kill 或者 Remove 就行了。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3>',11)),a("p",null,[e[9]||(e[9]=r("DockerUI 使用了 docker 遠程 API 提供了一個很棒的管理 docker 容器的 web 界面。它的開發者們完全使用 HTML 和 JS 設計、開發了這個應用。目前這個程序還處於開發中，並且還有大量的工作要完成，所以我們並不推薦將它應用在生產環境。它可以幫助用户簡單的完成管理容器和鏡像，而且只需要一點點工作。如果想要為 DockerUI 做貢獻，可以訪問它們的 ",-1)),t(o,{href:"https://github.com/crosbymichael/dockerui/"},{default:n(()=>[...e[8]||(e[8]=[r("Github 倉庫",-1)])]),_:1}),e[10]||(e[10]=r("。如果有問題、建議、反饋，請寫在下面的評論框，這樣我們就可以修改或者更新我們的內容。謝謝。",-1))]),e[28]||(e[28]=a("hr",null,null,-1)),a("p",null,[e[12]||(e[12]=r("via: ",-1)),t(o,{href:"http://linoxide.com/linux-how-to/setup-dockerui-web-interface-docker/"},{default:n(()=>[...e[11]||(e[11]=[r("http://linoxide.com/linux-how-to/setup-dockerui-web-interface-docker/",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=r("作者：",-1)),t(o,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[13]||(e[13]=[r("Arun Pyasi",-1)])]),_:1}),e[17]||(e[17]=r(" 譯者：",-1)),t(o,{href:"https://github.com/oska874"},{default:n(()=>[...e[14]||(e[14]=[r("oska874",-1)])]),_:1}),e[18]||(e[18]=r(" 校對：",-1)),t(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[15]||(e[15]=[r("wxy",-1)])]),_:1})]),a("p",null,[e[21]||(e[21]=r("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[19]||(e[19]=[r("LCTT",-1)])]),_:1}),e[22]||(e[22]=r(" 原創編譯，",-1)),t(o,{href:"https://linux.cn/"},{default:n(()=>[...e[20]||(e[20]=[r("Linux中國",-1)])]),_:1}),e[23]||(e[23]=r(" 榮譽推出",-1))])])}const S=i(c,[["render",k]]);export{g as __pageData,S as default};
